import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import {htFromTtc,euro,offersOf,unitWords,lotTtc} from './pricing.mjs';
const config=JSON.parse(fs.readFileSync('data/site.json','utf8'));
const products=JSON.parse(fs.readFileSync('data/products.json','utf8'));
const formulas=JSON.parse(fs.readFileSync('data/formulas.json','utf8'));
const production=process.argv.includes('--production');
const staging=process.argv.includes('--staging');
const preview=!production;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dims=p=>p.imageSize||[610,915];
// Styles et scripts : URL suivie d'une empreinte du contenu, pour que chaque mise à jour soit chargée
// immédiatement malgré le cache navigateur de 24 h (netlify.toml).
const asset=(()=>{const memo={};return f=>`/assets/${f}?v=${memo[f]??=crypto.createHash('sha1').update(fs.readFileSync(path.join('assets',f))).digest('hex').slice(0,10)}`;})();
if(production){
 const required=['url','email','company','address','registration','director','legalStatus','privacyContact','retention','legalBasis','recipients','internationalTransfers','rightsText','hostLegal','commercialContentApproved','legalContentApproved','formReceptionTested','launchChecksApproved'];
 const missing=required.filter(k=>!config[k]);
 if(products.some(p=>p.confirmed&&(!p.taxStatus||p.taxStatus.includes('préciser'))))missing.push('fiscalité produits');
 if(!config.vatRateConfirmed)missing.push('taux de TVA (vatRateConfirmed)');
 if(missing.length)throw new Error('Publication bloquée : compléter/valider '+missing.join(', '));
 if(!/^https:\/\/[^/]+\/?$/.test(config.url))throw new Error('URL HTTPS du site attendue.');
}
// dist/ est entièrement régénéré : on le vide pour ne jamais publier une page supprimée ou renommée.
const dist='dist';fs.rmSync(dist,{recursive:true,force:true});fs.mkdirSync(dist,{recursive:true});fs.cpSync('assets',path.join(dist,'assets'),{recursive:true});
const published=products.filter(p=>p.confirmed||preview);
// Espace pro : projet Supabase fourni par les variables d'environnement Netlify SUPABASE_URL et SUPABASE_ANON_KEY
// (clé publique ; la sécurité repose sur les règles de supabase/schema.sql). Sans elles, l'espace s'affiche « bientôt ouvert ».
const supabase=(()=>{const url=(process.env.SUPABASE_URL||'').trim().replace(/\/$/,''),key=(process.env.SUPABASE_ANON_KEY||'').trim();
 if(!url&&!key)return null;
 if(!/^https:\/\/[a-z0-9-]+\.supabase\.co$/.test(url)||!/^[A-Za-z0-9._-]{20,}$/.test(key))throw new Error('Espace pro : SUPABASE_URL (https://xxxx.supabase.co) ou SUPABASE_ANON_KEY invalide.');
 return {url,key};})();

