const pages=[];
function page(url,title,description,body,{noCta=false,nav=url,espace=false}={}){
 const canonical=config.url?config.url.replace(/\/$/,'')+url:'';
 let html=`<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#183c35"><title>${esc(title)} | BBD Officiel</title><meta name="description" content="${esc(description)}">${preview?'<meta name="robots" content="noindex,nofollow">':''}${canonical?`<link rel="canonical" href="${esc(canonical)}"><meta property="og:url" content="${esc(canonical)}">`:''}<meta property="og:title" content="${esc(title)} | BBD Officiel"><meta property="og:description" content="${esc(description)}"><meta property="og:type" content="website"><meta property="og:locale" content="fr_FR"><link rel="icon" type="image/svg+xml" href="/assets/favicon.svg"><script src="${asset('prix.js')}"></script><link rel="stylesheet" href="${asset('style.css')}"><link rel="stylesheet" href="${asset('brand.css')}"><link rel="stylesheet" href="${asset('ui.css')}">${espace&&supabase?`<meta name="bbd-supabase-url" content="${esc(supabase.url)}"><meta name="bbd-supabase-key" content="${esc(supabase.key)}">`:''}${espace?`<script src="${asset('espace.js')}" defer></script>`:''}<script src="${asset('app.js')}" defer></script></head><body><a href="#contenu" class="skip">Aller au contenu</a>${preview?'<div class="preview-banner">APERÇU DE TRAVAIL · Formules fictives · Tarifs fournis TTC, HT calculé · Envoi désactivé.<a href="/apercu/">À compléter ensemble ↗</a></div>':''}<header><div class="wrap nav">${brand}<button class="menu-toggle" aria-controls="navigation" aria-expanded="false">Menu <span aria-hidden="true">☰</span></button><nav id="navigation" class="navlinks" aria-label="Navigation principale">${navItems.map(([text,href])=>`<a href="${href}"${nav===href?' aria-current="page"':''}>${text}</a>`).join('')}<a class="nav-account" href="/espace-pro/"${nav==='/espace-pro/'?' aria-current="page"':''}>${icon('user')}<span>Espace pro</span></a>${button('Demander un devis',q('','','','menu'),'nav-cta')}</nav></div></header><main id="contenu">${body}</main>${footer()}${noCta?'':`<div class="mobile-cta"><span>Une idée en tête ?<br><strong>Devis sans engagement.</strong></span>${button('Demander un devis',q('','','','barre-mobile'),'')}</div>`}</body></html>`;
 if(['/espace-pro/','/espace-pro/admin/'].includes(url)&&!preview)html=html.replace('<meta name="description"','<meta name="robots" content="noindex,nofollow"><meta name="description"');
 if(preview&&!staging&&['/devis/','/espace-pro/parrainage/'].includes(url))html=html.replace(/type="submit" class="(btn[^"]*)"/,'type="submit" class="$1" disabled data-preview-submit');
 const file=url==='/404.html'?'404.html':url==='/'?'index.html':url.slice(1)+'index.html';fs.mkdirSync(path.dirname(path.join(dist,file)),{recursive:true});fs.writeFileSync(path.join(dist,file),html);pages.push(url);
}
function footer(){
 return `<footer><div class="wrap"><div class="footer-top"><div>${brand}<p>Textiles personnalisés, friandises naturelles et accessoires pour celles et ceux qui font vivre le monde canin.</p><ul class="footer-assure"><li>${icon('shield')}Devis sans engagement</li><li>${icon('nocard')}Aucun paiement en ligne</li><li>${icon('euro')}Prix HT et TTC affichés</li></ul></div><div><h3>Catalogues</h3>${families.map(([id,t])=>`<a href="/solutions/${id}/">${t}</a>`).join('')}<a href="/solutions/">Toutes les solutions</a></div><div><h3>Pour qui ?</h3><a href="/pour-qui/">Tous les profils</a>${profiles.map(p=>`<a href="/univers/${p.id}/">${p.name}</a>`).join('')}<a href="/solutions/recompenses/">Particuliers & passionnés</a></div><div><h3>Votre projet</h3><a href="/devis/">Demander un devis</a><a href="/personnalisation/">Personnaliser avec votre logo</a><a href="/qui-sommes-nous/">Qui sommes-nous ?</a><a href="/espace-pro/">Espace pro : suivre mes demandes</a><a href="/espace-pro/parrainage/">Programme de parrainage</a>${config.email?`<a href="mailto:${esc(config.email)}">${esc(config.email)}</a>`:'<p class="footer-note">Coordonnées à intégrer dans la version finale.</p>'}${config.phone?`<a href="tel:${esc(config.phone.replace(/\s/g,''))}">${esc(config.phone)}</a>`:''}</div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} BBD Officiel · Le monde canin, à vos couleurs.</span><div><a href="/mentions-legales/">Mentions légales</a><a href="/confidentialite/">Confidentialité</a></div></div></div></footer>`;
}
// family : null = pas de parent ; '' = parent « Nos solutions » ; identifiant = « Nos solutions » puis le catalogue.
const crumbs=(title,family=null)=>`<nav class="wrap breadcrumb" aria-label="Fil d’Ariane"><a href="/">Accueil</a><span aria-hidden="true">/</span>${family!==null?`<a href="/solutions/">Nos solutions</a><span aria-hidden="true">/</span>`:''}${family?`<a href="/solutions/${family}/">${famTitle(family)}</a><span aria-hidden="true">/</span>`:''}<span aria-current="page">${title}</span></nav>`;
const heroMedia=m=>`<figure class="fam-media"><img src="${m[0]}" alt="${esc(m[3])}" width="${m[1]}" height="${m[2]}" fetchpriority="high">${m[4]?'<span class="visual-label">Mise en scène illustrative</span>':''}</figure>`;
