const assurances=[
 ['shield','Sans engagement','Vous recevez une proposition et vous validez avant toute commande.'],
 ['nocard','Aucun paiement en ligne','Rien à régler sur le site : la commande se fait sur devis.'],
 ['euro','Des prix clairs','Chaque tarif est affiché en HT et en TTC, lots et quantités compris.'],
 ['palette','À vos couleurs','Version avec votre logo proposée sur les textiles.']
];
const assuranceBand=()=>`<section class="assurance-band" aria-label="Nos engagements"><div class="wrap"><p class="assurance-title">Commandez <em>l’esprit tranquille.</em></p>${assurance()}</div></section>`;
const assurance=(cls='')=>`<ul class="assurance ${cls}" aria-label="Nos engagements">${assurances.map(([i,t,d])=>`<li>${icon(i,'ico ico-badge')}<div><strong>${t}</strong><span>${d}</span></div></li>`).join('')}</ul>`;
// Prix HT (professionnels) / TTC (particuliers) : les deux valeurs sont dans la page, le sélecteur choisit
// laquelle est mise en avant. Sans JavaScript : HT en avant et « soit … TTC ».
// Premier argument : montant TTC transmis ; htText reçoit le HT calculé, ttcText le TTC.
const both=(ttcValue,htText,ttcText)=>`<span class="when-ht">${htText(htFromTtc(ttcValue,config.vatRate))}</span><span class="when-ttc">${ttcText(ttcValue)}</span>`;
const taxSwitch=(cls='')=>`<div class="${('tax-switch '+cls).trim()}" role="group" aria-label="Affichage des prix"><span>Afficher les prix</span><button type="button" data-prix="ht" aria-pressed="true">HT · professionnels</button><button type="button" data-prix="ttc" aria-pressed="false">TTC · particuliers</button></div>`;
const saleTag=p=>{const packs=[...new Set(offersOf(p).map(o=>o.pack))];return packs.length===1&&packs[0]===1?'Au kilo':`Lot de ${packs.join(' ou ')}`;};
function pcard(p){
 const offers=offersOf(p),[one]=unitWords(p),[w,h]=dims(p);
 const min=offers.reduce((a,o)=>o.unit<a.unit?o:a);
 const from=offers.length>1?'dès ':'';
 const tags=[saleTag(p),p.offers?'':'Logo possible',swatchCount(p)?`${swatchCount(p)} coloris`:''].filter(Boolean);
 const price=p.lotPrice?both(lotTtc(min),v=>`<span><strong>${euro(v)}</strong> HT le lot de ${min.pack}</span><small>soit ${euro(lotTtc(min))} TTC</small>`,v=>`<span><strong>${euro(v)}</strong> TTC le lot de ${min.pack}</span><small>soit ${euro(htFromTtc(lotTtc(min),config.vatRate))} HT</small>`):both(min.unit,v=>`<span>${from}<strong>${euro(v)}</strong> HT / ${one}</span><small>soit ${euro(min.unit)} TTC</small>`,v=>`<span>${from}<strong>${euro(v)}</strong> TTC / ${one}</span><small>soit ${euro(htFromTtc(min.unit,config.vatRate))} HT</small>`);
 return `<article class="pcard"><div class="pcard-media">${p.image?`<img src="${esc(p.image)}" alt="${esc(p.alt)}" width="${w}" height="${h}" loading="lazy">`:`<div class="photo-pending"><span>Photo à venir</span></div>`}</div><div class="pcard-body"><ul class="pcard-tags">${tags.map(t=>`<li>${t}</li>`).join('')}</ul><h3><a href="/produits/${p.id}/">${esc(p.name)}</a></h3><p class="pcard-price">${price}</p><span class="pcard-cta" aria-hidden="true">Voir le produit${arrow}</span></div></article>`;
}
function catTile(id,cls=''){
 const m=famMeta[id],list=famProducts(id),[src,w,h,alt]=m.img;
 return `<a class="cat-tile ${cls}" href="/solutions/${id}/"><div class="cat-media"><img src="${src}" alt="${esc(alt)}" width="${w}" height="${h}" loading="lazy"></div><div class="cat-body"><div class="cat-head">${icon(m.icon,'ico ico-badge')}<div><h3>${famTitle(id)}</h3><span class="cat-count">${list.length} référence${list.length>1?'s':''}</span></div></div><p>${families.find(f=>f[0]===id)[3]}</p><ul class="cat-facts">${m.points.slice(1,3).map(([,t])=>`<li>${t}</li>`).join('')}</ul><span class="btn">${m.cta}${arrow}</span></div></a>`;
}
const catGrid=()=>`<div class="cat-grid">${['textiles','recompenses','accessoires'].map(id=>catTile(id)).join('')}</div>`;
function rail(id,title,lede,list,more){
 return `<section class="wrap section rail-section"><div class="section-head"><div><h2>${title}</h2><p class="lede">${lede}</p></div><div class="rail-tools">${taxSwitch('compact')}<div class="rail-nav" hidden><button type="button" data-rail="-1" aria-label="Produits précédents">${icon('arrowL')}</button><button type="button" data-rail="1" aria-label="Produits suivants">${icon('arrowR')}</button></div></div></div><div class="product-rail" tabindex="0" role="region" aria-label="${esc(id)}">${list.map(pcard).join('')}</div><div class="rail-more">${button(more[0],more[1],'outline')}</div></section>`;
}
const howSteps=[
 ['pointer','Choisissez','Parcourez les catalogues et ouvrez les fiches qui vous intéressent.'],
 ['sliders','Précisez','Formule, quantité, coloris, logo : le calculateur affiche le montant en HT et en TTC.'],
 ['doc','Recevez votre devis','Votre demande arrive avec votre sélection ; la proposition détaille les conditions et la livraison.'],
 ['check','Validez','Rien n’est lancé sans votre accord. Aucun paiement au moment de la demande.']
];
const howto=()=>`<ol class="howto">${howSteps.map(([i,t,d],n)=>`<li><span class="howto-ico">${icon(i)}<b>${n+1}</b></span><h3>${t}</h3><p>${d}</p></li>`).join('')}</ol>`;
const goodToKnow=()=>`<aside class="know" aria-labelledby="know-title"><h3 id="know-title">Bon à savoir</h3><dl><div>${icon('euro')}<dt>HT ou TTC ?</dt><dd>Professionnels, lisez les prix HT ; particuliers, les prix TTC. Le bouton « Afficher les prix » s’applique à tout le site.</dd></div><div>${icon('box')}<dt>Lots et vente au kilo</dt><dd>Textiles par lots de 4, BB Bed par lots de 3 ou de 10, friandises par lots ou au kilo. Le calculateur de chaque fiche fait le compte.</dd></div><div>${icon('palette')}<dt>Votre logo</dt><dd>Sur les textiles, une version avec votre logo est proposée au tarif affiché. Technique et emplacement sont précisés dans le devis.</dd></div><div>${icon('chat')}<dt>Pas encore décidé ?</dt><dd>Décrivez simplement votre besoin, vos quantités et votre échéance : la proposition se construit avec vous.</dd></div></dl></aside>`;
const howtoSection=(title='Commander, <em>simplement.</em>',lede='Quatre étapes, sans paiement en ligne : vous gardez la main jusqu’à la validation du devis.')=>`<section class="wrap section"><div class="section-head"><div><h2>${title}</h2><p class="lede">${lede}</p></div></div><div class="howto-wrap">${howto()}${goodToKnow()}</div></section>`;
const steps=`<ol class="howto">${[['chat','On échange','Votre univers, vos envies, vos quantités et votre échéance.'],['doc','On précise la proposition','Une sélection et un devis avec les conditions du projet.'],['check','Vous validez','Le visuel, les détails et la commande avant de lancer la suite.'],['box','Votre projet prend forme','Production et livraison selon les conditions convenues.']].map(([i,t,d],n)=>`<li><span class="howto-ico">${icon(i)}<b>${n+1}</b></span><h3>${t}</h3><p>${d}</p></li>`).join('')}</ol>`;
const faq=(items,title='Les réponses <em>utiles.</em>')=>`<section class="wrap section faq"><div><h2>${title}</h2><p class="faq-more">Une autre question ? ${link('Posez-la dans votre demande','/devis/?source=faq')}</p></div><div>${items.map(([question,answer])=>`<details><summary>${question}</summary><p>${answer}</p></details>`).join('')}</div></section>`;
const closing=(profile='')=>`<div class="wrap"><section class="closing"><div><h2>Prêt à vous <em>lancer ?</em></h2><p>Quelques informations suffisent : votre besoin, une quantité estimée, votre échéance. Vous recevez une proposition, sans engagement.</p><ul class="closing-assure"><li>${icon('shield')}Sans engagement</li><li>${icon('nocard')}Aucun paiement en ligne</li></ul></div><div class="closing-actions">${button('Demander un devis',q(profile,'','','fin-page'),'big')}${button('Voir les catalogues','/solutions/','outline')}</div></section></div>`;
const formulaCards=(profile='')=>formulas.filter(f=>(!profile||f.profile===profile)&&(preview||f.confirmed)).map(f=>`<article class="formula"><div class="formula-body"><div class="label">${esc(f.audience)} · ${f.confirmed?'À personnaliser':'Exemple de formule'}</div><h3>${esc(f.name)}</h3><p>${esc(f.description)}</p><ul>${f.items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${button('Partir de cette idée',q(f.profile,f.name,'packs','formule-'+f.id))}</div></article>`).join('');
const formulaNote=()=>preview?'Exemples fictifs pour se projeter : compositions, références et conditions seront confirmées avant publication.':'Les compositions et les conditions applicables sont précisées dans votre devis.';
function audiences(){
 const list=[...profiles.map(p=>[p.icon,p.name,p.card,`/univers/${p.id}/`,`Les idées pour les ${p.name.toLowerCase()}`]),['heart','Particuliers & passionnés','Des friandises naturelles et un couchage douillet pour faire plaisir à votre chien, prix TTC affichés.','/pour-qui/#particuliers','Les idées pour les particuliers']];
 return `<div class="who-grid">${list.map(([i,n,t,h,c],k)=>`<a class="who-card${k===3?' who-card--accent':''}" href="${h}">${icon(i,'ico ico-badge')}<h3>${n}</h3><p>${t}</p><span class="who-go">${c}${arrow}</span></a>`).join('')}</div>`;
}
function clubMoment(){return `<section class="wrap section club-moment"><div class="club-moment-copy"><h2>Les détails créent<br><em>l’esprit d’équipe.</em></h2><p>Une tenue commune installe la cohérence, facilite l’identification et donne au collectif une présence immédiatement reconnaissable — sur le ring comme au bord du terrain.</p><div class="actions">${button('Équiper mon club',q('clubs','Tenues d’équipe','textiles','moment-club'))}${link('Les idées pour les clubs','/univers/clubs/')}</div><small>Visuel de campagne généré à partir des références produits.</small></div><div class="club-moment-image" data-depth><img src="/assets/campagne-club-bbd.jpg" alt="Mise en scène illustrative de deux membres d’un club canin préparant un chien avant une compétition" width="1200" height="1500" loading="lazy"><span class="visual-label">Mise en scène illustrative</span></div></section>`;}

