for(const [id,t,sub,d]of families){
 const list=famProducts(id),m=famMeta[id];
 const others=['textiles','recompenses','accessoires'].filter(x=>x!==id);
 const title=t.replace(' & ',' &<br><em>')+(t.includes(' & ')?'</em>':'');
 const hero=`<section class="wrap fam-hero"><div><p class="kicker">${icon(m.icon)}${id==='packs'?'Exemples d’ensembles':`${list.length} référence${list.length>1?'s':''}`}</p><h1>${title}</h1><p class="lead">${d}</p><ul class="points">${m.points.map(([i,x])=>`<li>${icon(i)}${x}</li>`).join('')}</ul><div class="actions">${id==='packs'?button('Décrire mon besoin',q('',t,id,'famille-'+id),'big'):button(`Voir les ${list.length} produits`,'#produits','big')+button('Demander un devis',q('',t,id,'famille-'+id),'outline big')}</div></div>${m.img?heroMedia(m.img):''}</section>`;
 const body=id==='packs'
  ?`<section class="dark-section on-dark"><div class="wrap"><div class="formula-grid">${formulaCards()}</div><p class="formula-note">${formulaNote()}</p></div></section>`
  :`<section class="wrap section section--tight" id="produits"><div class="grid-head"><h2>${list.length} référence${list.length>1?'s':''} <em>à découvrir</em></h2>${taxSwitch('compact')}</div><div class="pgrid">${list.map(pcard).join('')}</div><p class="fine">Prix transmis TTC ; HT calculé avec une TVA à ${config.vatRate} %${preview&&!config.vatRateConfirmed?' (taux à confirmer)':''}. Tailles, disponibilités, livraison et délais sont précisés dans le devis.</p></section>`;
 page(`/solutions/${id}/`,t+' pour vos projets canins',d,`${crumbs(t,'')}${hero}${assuranceBand()}${body}<section class="wrap section"><div class="section-head"><div><h2>Découvrez <em>aussi.</em></h2></div></div><div class="cat-grid cat-grid--duo">${(id==='packs'?['textiles','recompenses','accessoires']:others).map(x=>catTile(x)).join('')}</div></section>${closing()}`,{nav:`/solutions/${id}/`});
}

// ---------------------------------------------------------------------------
// Fiches produits
// ---------------------------------------------------------------------------
function productGallery(p){
 const [w,h]=dims(p);
 if(!p.image)return `<div class="product-photo"><div class="photo-pending"><span>Photo à venir</span><small>${esc(p.name)}</small></div></div>`;
 if(!p.swatches)return `<div class="product-photo"><img src="${esc(p.image)}" alt="${esc(p.alt)}" width="${w}" height="${h}" fetchpriority="high"><span>Photo fournie par BBD Officiel</span>${(p.gallery||[]).map(g=>`<img src="${esc(g.image)}" alt="${esc(g.alt)}" width="${w}" height="${h}" loading="lazy">`).join('')}</div>`;
 const motifs=[...new Set(p.swatches.map(s=>s.motif))];
 const start=p.swatches.find(s=>s.image===p.image),[tw,th]=p.thumbSize||[240,180];
 return `<div class="product-photo has-swatches"><figure class="swatch-stage"><img id="swatch-main" src="${esc(p.image)}" alt="${esc(p.alt)}" width="${w}" height="${h}" fetchpriority="high"><figcaption><span id="swatch-caption">${esc(start?start.label:p.name)}</span> · Photo fournie par BBD Officiel</figcaption></figure><div class="swatch-groups">${motifs.map(m=>`<div class="swatch-group"><p class="swatch-title">${esc(m)}</p><div class="swatch-list">${p.swatches.filter(s=>s.motif===m).map(s=>`<a class="swatch" href="${esc(s.image)}" data-image="${esc(s.image)}" data-alt="${esc(s.alt)}" data-label="${esc(s.label)}" data-coloris="${s.range?'':esc(s.label)}"${s===start?' aria-current="true"':''}><img src="${esc(s.thumb)}" alt="" width="${tw}" height="${th}" loading="lazy"><span>${esc(s.short??(s.range?'Gamme':s.label.slice(m.length+1)))}</span></a>`).join('')}</div></div>`).join('')}</div></div>`;
}
for(const p of published){
 if(!/^[a-z0-9-]+$/.test(p.id))throw new Error('Identifiant produit invalide');
 const offers=offersOf(p),[one,many]=unitWords(p),first=offers[0],choice=p.choiceLabel||'Version';
 const samePack=offers.every(o=>o.pack===first.pack);
 const m=famMeta[p.family]||{icon:'tag'};
 const rate=config.vatRate;
 const priceCards=offers.map(o=>p.lotPrice?`<div><span>${esc(o.label)} pièces</span><strong>${both(lotTtc(o),v=>`${euro(v)} <small>HT le lot</small>`,v=>`${euro(v)} <small>TTC le lot</small>`)}</strong><p>${both(lotTtc(o),()=>`soit ${euro(lotTtc(o))} TTC le lot de ${o.pack} ${many}`,()=>`soit ${euro(htFromTtc(lotTtc(o),rate))} HT le lot de ${o.pack} ${many}`)}</p></div>`:`<div><span>${esc(o.label)}</span><strong>${both(o.unit,v=>`${euro(v)} <small>HT / ${one}</small>`,v=>`${euro(v)} <small>TTC / ${one}</small>`)}</strong><p>${both(o.unit,()=>`soit ${euro(o.unit)} TTC / ${one}`,()=>`soit ${euro(htFromTtc(o.unit,rate))} HT / ${one}`)}</p>${o.pack>1?`<p>${both(lotTtc(o),v=>`${euro(v)} HT le lot de ${o.pack}`,v=>`${euro(v)} TTC le lot de ${o.pack}`)}</p>`:''}${o.note?`<p class="offer-note">${esc(o.note)}</p>`:''}</div>`).join('');
 const colorField=p.swatches?`<div class="field full"><label for="product-coloris">${esc(p.swatchLabel||'Motif et coloris')}</label><select id="product-coloris"><option value="">Plusieurs coloris ou à préciser</option>${[...new Set(p.swatches.filter(s=>!s.range).map(s=>s.motif))].map(mo=>`<optgroup label="${esc(mo)}">${p.swatches.filter(s=>s.motif===mo&&!s.range).map(s=>`<option>${esc(s.label)}</option>`).join('')}</optgroup>`).join('')}</select></div>`:'';
 const quoteUrl=q('',p.name,p.family,'produit-'+p.id)+'&'+new URLSearchParams({produit:p.id,quantite:first.pack,choix:choice,version:first.label});
 const info=[...(p.sections||[]).map(s=>`<details${s.open?' open':''}><summary>${esc(s.title)}</summary><ul class="product-points">${s.items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`),p.highlights?`<details open><summary>Les + produit</summary><ul class="product-points">${p.highlights.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:'',p.usage?`<details><summary>Utilisation</summary><p>${esc(p.usage)}</p></details>`:'',p.care?`<details><summary>Entretien</summary><ul class="product-points">${p.care.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:'',p.personalization?`<details open><summary>Personnalisation</summary><p>${esc(p.personalization)}</p></details>`:'',`<details><summary>${p.dimensions?'Dimensions, coloris et informations utiles':'Tailles, livraison et informations utiles'}</summary><p>${esc(p.details)}</p></details>`].join('');
 const related=famProducts(p.family).filter(x=>x.id!==p.id).slice(0,4);
 const chip=`<a class="pchip" href="/solutions/${p.family}/">${icon(m.icon)}${esc(famTitle(p.family))}</a>${p.confirmed?'':'<span class="pchip pchip--warn">Exemple fictif</span>'}`;
 page('/produits/'+p.id+'/',p.name,p.description,`${crumbs(esc(p.name),p.family)}<section class="wrap section section--tight product-layout">${productGallery(p)}<div class="product-content">${chip}<h1>${esc(p.name)}</h1>${p.dimensions?`<p class="product-spec">${esc(p.dimensions)}</p>`:''}<p class="product-lead">${esc(p.description)}</p>${taxSwitch()}<div class="price-options">${priceCards}</div><p class="tiny tax-note">Prix transmis TTC ; HT calculé avec une TVA à ${rate} %${preview&&!config.vatRateConfirmed?' (taux à confirmer)':''}.</p><div class="product-config" data-product="${esc(p.id)}" data-rate="${rate}" data-one="${one}" data-many="${many}"><h2>Préparez votre demande</h2><div class="form-grid"><div class="field"><label for="product-version">Votre ${choice.toLowerCase()}</label><select id="product-version">${offers.map(o=>`<option value="${esc(o.id)}" data-unit="${o.unit}" data-lot="${lotTtc(o)}" data-pack="${o.pack}" data-label="${esc(o.label)}">${esc(o.label)}</option>`).join('')}</select></div><div class="field"><label for="product-lots">${esc(p.lotsLabel||'Nombre de lots'+(samePack?' de '+first.pack:''))}</label><input id="product-lots" type="number" min="1" max="10000" step="1" value="1"></div>${colorField}</div><p id="product-total" role="status">${first.pack} ${first.pack>1?many:one} · ${euro(htFromTtc(lotTtc(first),rate))} HT · ${euro(lotTtc(first))} TTC</p><p class="tiny">Montant des articles uniquement. Frais de livraison et conditions précisés dans le devis.</p><a class="btn big" id="product-quote" href="${esc(quoteUrl)}">Demander un devis pour cette sélection${arrow}</a><ul class="mini-assure"><li>${icon('shield')}Sans engagement : vous validez le devis</li><li>${icon('nocard')}Aucun paiement en ligne</li><li>${icon('doc')}Votre sélection est jointe à la demande</li></ul></div>${info}</div></section>${related.length?`<section class="wrap section related"><div class="grid-head"><h2>Dans la même <em>famille.</em></h2>${link(`Tout le catalogue ${famMeta[p.family]?famMeta[p.family].nav.toLowerCase():''}`,`/solutions/${p.family}/`)}</div><div class="pgrid">${related.map(pcard).join('')}</div></section>`:''}${closing()}`,{nav:`/solutions/${p.family}/`});
}

