page('/personnalisation/','Personnalisation — De votre idée au projet','Préparez votre projet personnalisé : identité visuelle, usage, quantités et validation. Les possibilités sont confirmées pour chaque référence.',`${crumbs('Personnalisation')}${intro('Votre identité, le fil conducteur','À vos couleurs.<br><em>Dans les moindres détails.</em>','Un logo, un nom, une couleur : partons de ce qui vous représente pour construire une sélection cohérente.',button('Décrire mon idée',q('','Projet de personnalisation','','personnalisation'),'big')+button('Voir les textiles','/solutions/textiles/','outline big'),photo.salon)}<section class="wrap section"><div class="section-head"><div><h2>On avance <em>étape par étape.</em></h2><p class="lede">La personnalisation se définit selon le support retenu. Technique, emplacement, couleurs et faisabilité sont confirmés dans votre proposition.</p></div></div>${steps}</section><section class="wrap section content-split"><div><h2>Ce qui aide<br><em>à bien démarrer.</em></h2><p>Vous pouvez faire une première demande sans fichier. Votre logo et les détails visuels pourront être transmis pendant l’échange.</p></div><div class="use-grid"><article class="use-card">${icon('palette','ico ico-badge')}<h3>Votre identité</h3><p>Nom à afficher, logo si vous en avez un, couleurs souhaitées et droits d’utilisation du visuel.</p></article><article class="use-card">${icon('users','ico ico-badge')}<h3>Votre usage</h3><p>Destinataires, conditions d’utilisation, quantités et date éventuelle.</p></article></div></section>${faq([['Quel format de logo faut-il prévoir ?','Un fichier vectoriel, si vous en disposez, facilite souvent la préparation. Le format exact et les exigences seront précisés selon la technique retenue. Aucun fichier n’est demandé pour ce premier contact.'],['Quelles techniques proposez-vous ?','Les techniques disponibles seront détaillées une fois les supports et fournisseurs confirmés. Une technique de marquage ne sera pas promise sans vérification.'],['Quand valide-t-on le visuel ?','La proposition précise les étapes de validation. Le visuel et les détails de la commande sont à valider avant lancement, selon les modalités convenues.']])}${closing()}`);
// Qui sommes-nous ? — récit repris de bbd-officiel.fr/pages/qui-sommes-nous (texte et photos du propriétaire),
// développé sans ajouter de fait : parcours de Hamady, élevage du Dogue Argentin, rencontres, confort au quotidien.
const qsnChapters=[
 ['Au contact des chiens','Une passion née sur le terrain.','Avant de se consacrer à l’élevage du Dogue Argentin, Hamady travaillait dans la sécurité, au contact des chiens. C’est là, au quotidien et sur le terrain, qu’est née une passion qui l’accompagne encore aujourd’hui.','Ce point de départ explique l’esprit de BBD : partir du chien et de la vie qu’il partage avec vous, plutôt que d’un catalogue.'],
 ['L’élevage','Le Dogue Argentin, une vie de passionné.','Hamady s’est ensuite consacré à l’élevage du Dogue Argentin. L’élevage, c’est un quotidien concret : le repos des chiens, leurs récompenses, les expositions, et le lien avec les familles qui les accueillent.','C’est ce quotidien que BBD cherche à accompagner, de l’élevage jusqu’au foyer.'],
 ['Les rencontres','Des rencontres qui font grandir.','Au fil des élevages et des expositions, Hamady a rencontré d’autres passionnés, observé leurs pratiques et partagé leurs expériences.','Cette proximité avec les chiens et ceux qui vivent avec eux nourrit l’univers de BBD — et c’est aussi sur ces rendez-vous que nous nous rencontrons.'],
 ['Aujourd’hui','Le confort, au quotidien.','BBD réunit des couchages, des tapis et des friandises pour accompagner les habitudes de votre compagnon. Une idée simple guide la marque : lui réserver une vraie place dans votre quotidien.','Pour les éleveurs, les clubs et les organisateurs, BBD propose aussi des textiles à leurs couleurs, avec ou sans logo.']
];
const qsnPhotos=[['/assets/qsn-hamady.jpg',900,1351,'Hamady, fondateur de BBD, en tee-shirt BBD devant un tapis aux couleurs de la marque'],['/assets/bb-bed-gamme-tetris.jpg',1000,750,'Couchages BB Bed motif Tetris empilés en plusieurs coloris'],['/assets/qsn-repos.jpg',1100,897,'Chiot endormi sur un plaid à motifs de pattes'],['/assets/qsn-friandises.jpg',1200,799,'Assortiment de friandises naturelles présentées dans des caisses en bois']];
const pillars=[['paw','Histoire','Une marque née d’un parcours personnel, au contact des chiens, bien avant d’être une boutique.'],['trophy','Expérience','L’élevage du Dogue Argentin, les expositions et des années d’échanges avec d’autres passionnés.'],['heart','Qualité','Des couchages, des friandises naturelles et des textiles choisis pour le confort et le plaisir de votre compagnon.']];
page('/qui-sommes-nous/','Qui sommes-nous ? — L’histoire de BBD','Derrière BBD, il y a Hamady : un parcours au contact des chiens, l’élevage du Dogue Argentin et des années de rencontres entre passionnés.',`${crumbs('Qui sommes-nous ?')}<section class="wrap qsn-hero"><div><p class="kicker">${icon('paw')}Qui sommes-nous ?</p><h1>Une passion<br><em>née sur le terrain.</em></h1><p class="lead">Derrière BBD, il y a Hamady : un parcours au contact des chiens, l’élevage du Dogue Argentin et des années de rencontres avec celles et ceux qui partagent leur vie avec un chien. BBD est née de là.</p><div class="actions">${button('Découvrir nos catalogues','/solutions/','big')}${button('Échanger avec nous',q('','','','qui-sommes-nous'),'outline big')}</div><ul class="hero2-ticks"><li>${icon('paw')}Éleveur de Dogues Argentins</li><li>${icon('users')}Présent en élevage et en exposition</li><li>${icon('heart')}Confort et plaisir de votre chien</li></ul></div><figure class="qsn-portrait"><img src="${qsnPhotos[0][0]}" alt="${esc(qsnPhotos[0][3])}" width="${qsnPhotos[0][1]}" height="${qsnPhotos[0][2]}" fetchpriority="high"><figcaption>Hamady, fondateur de BBD</figcaption></figure></section>
<section class="section qsn-story"><div class="wrap"><div class="section-head"><div><h2>Une histoire <em>en quatre temps.</em></h2><p class="lede">Du terrain à l’élevage, de l’élevage aux expositions, et des expositions à BBD : un même fil, le chien et ceux qui vivent avec lui.</p></div></div><ol class="chapters">${qsnChapters.map(([k,t,a,b],n)=>`<li class="chapter"><span class="chapter-num" aria-hidden="true">${n+1}</span><div><p class="chapter-kicker">${k}</p><h3>${t}</h3><p>${a}</p><p class="chapter-plus">${b}</p></div></li>`).join('')}</ol></div></section>
<section class="wrap section"><div class="qsn-mosaic">${qsnPhotos.slice(1).map(([src,w,h,alt],n)=>`<figure class="qsn-tile qsn-tile--${n+1}"><img src="${src}" alt="${esc(alt)}" width="${w}" height="${h}" loading="lazy"></figure>`).join('')}<figure class="qsn-tile qsn-tile--sig"><img src="/assets/logo-signature-web.jpg" alt="BBD — Histoire, expérience, qualité" width="800" height="800" loading="lazy"></figure></div></section>
<section class="wrap section"><div class="section-head"><div><h2>Histoire, expérience, <em>qualité.</em></h2><p class="lede">Les trois mots de la signature BBD, et ce qu’ils veulent dire pour vous.</p></div></div><div class="pillars">${pillars.map(([i,t,d])=>`<article class="pillar">${icon(i,'ico ico-badge')}<h3>${t}</h3><p>${d}</p></article>`).join('')}</div></section>
${assuranceBand()}
<section class="wrap section" id="catalogues"><div class="section-head"><div><h2>Ce que BBD <em>vous propose.</em></h2><p class="lede">Des textiles à vos couleurs, des friandises naturelles et un couchage douillet, avec des prix HT et TTC affichés sur chaque fiche.</p></div>${link('Toutes les solutions','/solutions/')}</div>${catGrid()}</section>
<section class="wrap section"><div class="qsn-meet"><div>${icon('chat','ico ico-badge')}<h2>Rencontrés sur un salon ou <em>en exposition ?</em></h2><p>C’est souvent là que tout commence. Dites-nous où nous nous sommes croisés et ce dont vous avez besoin : nous reprenons la discussion là où elle s’est arrêtée.</p></div><div class="closing-actions">${button('Échanger avec nous',q('','','','qui-sommes-nous-salon'),'big')}${button('Voir les friandises','/solutions/recompenses/','outline')}</div></div></section>${closing()}`);
const input=(name,label,type='text',required=false,extra='')=>`<div class="field"><label for="${name}">${label}${required?' *':''}</label><input id="${name}" name="${name}" type="${type}" ${required?'required':''} maxlength="200" ${extra}></div>`;
const select=(name,label,options,required=false)=>`<div class="field"><label for="${name}">${label}${required?' *':''}</label><select id="${name}" name="${name}" ${required?'required':''}><option value="">Choisir…</option>${options.map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}</select></div>`;
page('/devis/','Demander un devis','Décrivez votre projet canin : votre structure, votre besoin et vos coordonnées. Une demande sans engagement et sans paiement en ligne.',`${crumbs('Demander un devis')}${intro('Devis sans engagement','Parlons de<br><em>votre projet.</em>','Une idée précise ou une envie à explorer ? Dites-nous où vous en êtes. Les champs marqués d’un * suffisent pour commencer.')}<section class="wrap section section--tight form-layout"><form id="quote-form" class="quote-form" name="devis-bbd" method="POST" action="/merci/" ${(!preview||staging)?'data-netlify="true" netlify-honeypot="bot-field"':''} data-preview="${preview&&!staging}"><input type="hidden" name="form-name" value="devis-bbd"><input type="hidden" name="provenance" value="devis"><input type="hidden" name="campagne" value=""><input type="hidden" name="produit" value=""><input type="hidden" name="version" value=""><input type="hidden" name="coloris" value=""><p class="hp"><label>Ne pas remplir <input name="bot-field" tabindex="-1" autocomplete="off"></label></p>${preview?`<div class="notice warning">${staging?'Test technique de réception : ne saisir que des données de test.':'Aperçu : vous pouvez remplir et vérifier le formulaire. Aucune demande ne sera transmise.'}</div>`:''}<fieldset><legend>01 · Votre projet</legend><div class="form-grid">${select('profil','Vous êtes',[['eleveurs','Éleveur'],['clubs','Club de race / de discipline'],['evenements','Société canine / organisateur'],['passionne','Propriétaire / passionné'],['autre','Autre structure']],true)}${select('famille','Ce qui vous intéresse',families.map(([id,t])=>[id,t]))}<div class="field full"><label for="objet">Votre besoin en quelques mots *</label><input name="objet" id="objet" required maxlength="160" placeholder="Ex. : équiper notre équipe pour une exposition"></div>${input('quantite','Quantité estimée','number',false,'min="1" max="1000000" inputmode="numeric"')}${input('budget','Budget indicatif','text',false,'placeholder="Facultatif, même approximatif"')}<div class="field full"><label for="message">Un peu plus sur votre projet</label><textarea id="message" name="message" maxlength="5000" placeholder="Vos envies, vos contraintes, le salon où nous nous sommes rencontrés…"></textarea></div><label class="check field full check-cagnotte"><input type="checkbox" name="cagnotte" value="oui"><span>${icon('piggy')}J’ai un code de parrainage : je souhaite utiliser ma cagnotte sur ce devis.</span></label></div></fieldset><fieldset id="event-fields"><legend>Votre événement · facultatif</legend><div class="form-grid">${input('date-evenement','Date de l’événement','date')}${input('lieu-evenement','Lieu de l’événement')}</div></fieldset><fieldset id="textile-fields"><legend>Vos tenues · facultatif</legend><div class="form-grid">${input('personnes','Nombre de personnes','number',false,'min="1"')}${input('tailles','Tailles envisagées','text',false,'placeholder="Ex. : 5 M, 8 L, 3 XL"')}</div></fieldset><fieldset id="pack-fields"><legend>Votre formule · facultatif</legend><div class="field"><label for="composition">Composition souhaitée</label><textarea id="composition" name="composition" maxlength="2000" placeholder="Les éléments que vous aimeriez associer…"></textarea></div></fieldset><fieldset><legend>02 · Pour vous répondre</legend><div class="form-grid">${input('nom','Votre nom','text',true,'autocomplete="name"')}${input('email','Votre e-mail','email',true,'autocomplete="email"')}${input('structure','Nom de la structure','text',false,'autocomplete="organization"')}${input('telephone','Téléphone','tel',false,'autocomplete="tel"')}${input('livraison','Ville / département de livraison','text',false,'autocomplete="address-level2"')}</div></fieldset><label class="check"><input type="checkbox" name="confidentialite" value="lu" required><span>J’ai pris connaissance de la <a href="/confidentialite/" target="_blank" rel="noopener">politique de confidentialité (nouvel onglet)</a> relative à ma demande. *</span></label><p class="preview-help">Ces informations servent à traiter votre demande. Si votre visite provient d’un lien de salon, son identifiant est joint à la demande. Aucune inscription automatique à une newsletter.</p><p class="espace-hint" hidden>${icon('user')}<span>Connecté à votre espace pro (<strong></strong>) : cette demande s’ajoutera automatiquement à votre suivi.</span></p><p id="form-status" class="form-status" role="status" aria-live="polite" tabindex="-1"></p><button type="submit" class="btn big">${preview&&!staging?'Vérifier ma demande':'Envoyer ma demande'} <span aria-hidden="true">→</span></button><noscript><p class="notice">${preview&&!staging?'Aucun envoi n’est possible dans cet aperçu.':'Le formulaire fonctionne également sans JavaScript.'}</p></noscript></form><aside class="form-aside"><h2>Pas besoin d’avoir<br><em>tout décidé.</em></h2><p>Le premier échange sert à préciser les choses ensemble.</p><ul class="aside-steps">${[['chat','Vous décrivez votre besoin'],['doc','Vous recevez une proposition détaillée'],['check','Vous validez, ou non : sans engagement']].map(([i,t])=>`<li>${icon(i)}${t}</li>`).join('')}</ul><span class="tag">${icon('nocard')}Aucun paiement à cette étape.</span><p class="aside-espace">${icon('user')}<span>Vous avez un espace pro ? <a class="inline-link" href="/espace-pro/">Connectez-vous</a> avant d’envoyer : votre demande apparaîtra dans votre suivi.</span></p>${config.email?`<p>Un contact direct ?<br><a class="inline-link" href="mailto:${esc(config.email)}">${esc(config.email)}</a></p>`:''}</aside></section>`,{noCta:true,espace:true});
page('/merci/','Votre demande a été transmise','Les prochaines étapes de votre demande auprès de BBD Officiel.',`<section class="wrap success">${eyebrow('La suite de votre projet')}<h1>${preview?'L’aperçu s’arrête ici.':'Merci pour votre demande.'}</h1><p>${preview?'Cette page illustre la confirmation qui sera affichée après un envoi réussi. Aucune demande n’a été transmise depuis cet aperçu.':'Votre demande a été transmise. BBD Officiel en prendra connaissance pour préciser votre besoin et préparer la suite avec vous. Vous pourrez transmettre votre logo et les informations complémentaires pendant l’échange.'}</p><p class="merci-ref" hidden>${icon('check')}<span>Référence de votre demande : <strong></strong>. Suivez son avancement dans votre espace pro.</span></p><div class="actions">${button('Suivre mes demandes','/espace-pro/')}${button('Explorer les catalogues','/solutions/','outline')}</div></section>`,{noCta:true});
// ---------------------------------------------------------------------------
// Programme de parrainage : présentation et demande de code (soumise à validation de BBD).
// Le code et la cagnotte s'affichent ensuite dans l'espace pro (table parrainages de supabase/schema.sql).
// Aucun taux ni montant n'est annoncé : les conditions sont précisées par BBD à la validation.
// ---------------------------------------------------------------------------
const parrainSteps=[
 ['doc','Demandez votre code','Remplissez le court formulaire de cette page : votre structure, vos coordonnées et le code que vous aimeriez.'],
 ['check','BBD valide votre demande','Chaque demande est étudiée. Une fois validée, votre code promo est créé à votre nom et s’affiche dans votre espace pro.'],
 ['share','Partagez-le autour de vous','Familles adoptantes, adhérents, partenaires : ils l’utilisent pour leurs achats sur la boutique bbd-officiel.fr.'],
 ['piggy','Votre cagnotte grandit','Chaque achat réalisé avec votre code alimente votre cagnotte, déduite directement de vos prochains devis professionnels.']
];
const parrainWho=[
 ['paw','Éleveurs','Glissez votre code dans le dossier remis aux familles au départ d’un chiot : elles équipent leur compagnon, vous cumulez pour votre élevage.'],
 ['users','Clubs','Partagez-le avec vos adhérents : leurs achats personnels alimentent une cagnotte utile pour les tenues et les récompenses du club.'],
 ['trophy','Organisateurs','Diffusez-le auprès de vos participants et exposants : la cagnotte allège le devis de votre prochain événement.'],
 ['heart','Partenaires du monde canin','Vous accompagnez des propriétaires de chiens ? Recommandez BBD avec votre code et cumulez pour vos propres achats.']
];
const parrainIdeas=[['paw','Au départ d’un chiot'],['chat','Sur vos réseaux sociaux'],['users','Dans la lettre du club'],['trophy','Sur votre stand en exposition'],['tag','Sur vos cartes de visite'],['mail','Dans vos e-mails aux familles']];
const parrainCard=`<figure class="parrain-card" aria-label="Exemple de code de parrainage"><div class="parrain-card-top"><span>BBD · Parrainage</span><span class="parrain-ex">Exemple</span></div><p class="parrain-code-label">Votre code</p><p class="parrain-code">VOTRE-ELEVAGE</p><ol class="parrain-flow"><li>${icon('share')}<span>Vos contacts l’utilisent sur <strong>bbd-officiel.fr</strong></span></li><li>${icon('piggy')}<span>Votre <strong>cagnotte</strong> se remplit à chaque achat</span></li><li>${icon('doc')}<span>Elle est <strong>déduite de vos devis</strong> professionnels</span></li></ol></figure>`;
const parrainPromo=()=>`<section class="parrain-promo"><div>${icon('gift','ico ico-badge')}<p class="parrain-promo-kicker">Programme de parrainage</p><h2>Partagez votre code, <em>cumulez pour vos devis.</em></h2><p>Chaque achat de vos contacts sur bbd-officiel.fr avec votre code alimente une cagnotte, déduite directement de vos devis professionnels.</p></div><div class="closing-actions">${button('Découvrir le parrainage','/espace-pro/parrainage/','big')}${button('Demander mon code','/espace-pro/parrainage/#demande','outline')}</div></section>`;
const parrainForm=`<div class="parrain-form-col"><form id="parrainage-form" class="quote-form" name="parrainage-bbd" method="POST" action="/espace-pro/parrainage/" ${(!preview||staging)?'data-netlify="true" netlify-honeypot="bot-field"':''} data-preview="${preview&&!staging}"><input type="hidden" name="form-name" value="parrainage-bbd"><p class="hp"><label>Ne pas remplir <input name="bot-field" tabindex="-1" autocomplete="off"></label></p>${preview?`<div class="notice warning">${staging?'Test technique de réception : ne saisir que des données de test.':'Aperçu : vous pouvez remplir et vérifier le formulaire. Aucune demande ne sera transmise.'}</div>`:''}<fieldset><legend>01 · Votre structure</legend><div class="form-grid">${select('profil','Vous êtes',[['eleveur','Éleveur'],['club','Club de race / de discipline'],['organisateur','Organisateur d’événements'],['partenaire','Partenaire du monde canin'],['autre','Autre structure']],true)}${input('structure','Élevage, club ou structure','text',true,'autocomplete="organization"')}<div class="field"><label for="code">Code souhaité</label><input id="code" name="code" type="text" maxlength="30" pattern="[A-Za-z0-9\\-]{3,30}" placeholder="Ex. : ELEVAGE-DES-PLAINES" autocapitalize="characters"><small>De 3 à 30 caractères : lettres, chiffres et tirets.</small></div>${input('site','Site ou réseau social','text',false,'placeholder="Facultatif"')}<div class="field full"><label for="diffusion">Comment pensez-vous partager votre code ?</label><textarea id="diffusion" name="diffusion" maxlength="2000" placeholder="Familles adoptantes, adhérents, réseaux sociaux, expositions…"></textarea></div></div></fieldset><fieldset><legend>02 · Vos coordonnées</legend><div class="form-grid">${input('nom','Votre nom','text',true,'autocomplete="name"')}${input('email','Votre e-mail','email',true,'autocomplete="email"')}${input('telephone','Téléphone','tel',false,'autocomplete="tel"')}</div><p class="preview-help">Indiquez l’adresse de votre espace pro : votre code et votre cagnotte s’y afficheront.</p></fieldset><label class="check"><input type="checkbox" name="confidentialite" value="lu" required><span>J’ai pris connaissance de la <a href="/confidentialite/" target="_blank" rel="noopener">politique de confidentialité (nouvel onglet)</a> relative à ma demande. *</span></label><p class="form-status" role="status" aria-live="polite" tabindex="-1"></p><button type="submit" class="btn big">${preview&&!staging?'Vérifier ma demande':'Demander mon code'} <span aria-hidden="true">→</span></button></form><div id="parrainage-ok" class="espace-box parrain-ok" hidden tabindex="-1">${icon('check','ico ico-badge')}<h2>Demande <em>bien reçue.</em></h2><p>BBD Officiel étudie votre demande. Après validation, votre code est créé : il s’affiche dans votre espace pro, avec votre cagnotte.</p><div class="actions">${button('Accéder à mon espace pro','/espace-pro/')}</div></div></div>`;
page('/espace-pro/parrainage/','Programme de parrainage — Partagez votre code BBD','Demandez votre code de parrainage BBD : chaque achat de vos contacts sur bbd-officiel.fr alimente une cagnotte déduite de vos devis professionnels.',`<nav class="wrap breadcrumb" aria-label="Fil d’Ariane"><a href="/">Accueil</a><span aria-hidden="true">/</span><a href="/espace-pro/">Espace pro</a><span aria-hidden="true">/</span><span aria-current="page">Parrainage</span></nav>
<section class="wrap qsn-hero parrain-hero"><div><p class="kicker">${icon('gift')}Programme de parrainage</p><h1>Partagez votre code.<br><em>Cumulez pour vos devis.</em></h1><p class="lead">Éleveurs, clubs, organisateurs, partenaires : recevez un code promo à votre nom. Chaque achat réalisé avec ce code sur la boutique bbd-officiel.fr alimente votre cagnotte, déduite directement de vos devis sur ce site professionnel.</p><div class="actions">${button('Demander mon code','#demande','big')}${button('Accéder à mon espace pro','/espace-pro/','outline big')}</div><ul class="hero2-ticks"><li>${icon('tag')}Un code promo à votre nom</li><li>${icon('piggy')}Une cagnotte à chaque achat</li><li>${icon('doc')}Déduite de vos devis</li></ul></div>${parrainCard}</section>
<section class="wrap section"><div class="section-head"><div><h2>Comment ça <em>marche ?</em></h2><p class="lede">Quatre étapes, de la demande de code à la cagnotte déduite de votre devis.</p></div></div><ol class="howto">${parrainSteps.map(([i,t,d],n)=>`<li><span class="howto-ico">${icon(i)}<b>${n+1}</b></span><h3>${t}</h3><p>${d}</p></li>`).join('')}</ol></section>
<section class="section parrain-duo-section"><div class="wrap"><div class="section-head"><div><h2>Un code, <em>deux gagnants.</em></h2><p class="lede">Vos contacts profitent d’un code promo ; vous cumulez pour vos achats professionnels.</p></div></div><div class="parrain-duo"><article>${icon('heart','ico ico-badge')}<p class="parrain-duo-kicker">Pour vos contacts</p><h3>Un code promo sur la boutique</h3><p>Ils saisissent votre code lors de leurs achats sur bbd-officiel.fr, pour faire plaisir à leur chien.</p></article><span class="parrain-duo-link" aria-hidden="true">${icon('arrowR')}</span><article class="parrain-duo-you">${icon('piggy','ico ico-badge')}<p class="parrain-duo-kicker">Pour vous</p><h3>Une cagnotte qui se cumule</h3><p>Chaque achat réalisé avec votre code alimente votre cagnotte, déduite directement de vos devis : textiles à vos couleurs, friandises, couchages.</p></article></div></div></section>
<section class="wrap section"><div class="section-head"><div><h2>Pensé pour <em>votre réseau.</em></h2><p class="lede">Vous êtes au contact de nombreux propriétaires de chiens : votre recommandation compte, elle vous rapporte aussi.</p></div></div><div class="pillars parrain-who">${parrainWho.map(([i,t,d])=>`<article class="pillar">${icon(i,'ico ico-badge')}<h3>${t}</h3><p>${d}</p></article>`).join('')}</div><div class="parrain-ideas"><p class="parrain-ideas-title">Où partager votre code ?</p><ul>${parrainIdeas.map(([i,t])=>`<li>${icon(i)}${t}</li>`).join('')}</ul></div></section>
<section class="wrap section"><div class="qsn-meet"><div>${icon('user','ico ico-badge')}<h2>Votre cagnotte, <em>toujours à portée.</em></h2><p>Dans votre espace pro, retrouvez votre code, prêt à copier, le montant de votre cagnotte et les sommes déduites de chacun de vos devis.</p></div><div class="closing-actions">${button('Accéder à mon espace pro','/espace-pro/','big')}${button('Demander un devis',q('','','','parrainage'),'outline')}</div></div></section>
<section class="wrap section section--tight" id="demande"><div class="section-head"><div><h2>Demandez votre <em>code de parrainage.</em></h2><p class="lede">Deux minutes suffisent. Votre code est créé après validation par BBD Officiel.</p></div></div><div class="form-layout">${parrainForm}<aside class="form-aside"><h2>Soumis à<br><em>validation.</em></h2><p>Le programme est réservé aux professionnels et partenaires du monde canin. Chaque demande est étudiée par BBD Officiel avant la création du code.</p><ul class="aside-steps">${[['doc','Vous envoyez votre demande'],['check','BBD la valide et crée votre code'],['user','Code et cagnotte dans votre espace pro']].map(([i,t])=>`<li>${icon(i)}${t}</li>`).join('')}</ul><span class="tag">${icon('nocard')}Aucun paiement pour demander votre code.</span></aside></div></section>
${faq([['Qui peut demander un code ?','Les professionnels et partenaires du monde canin : éleveurs, clubs, organisateurs d’événements et acteurs qui accompagnent des propriétaires de chiens. Chaque demande est soumise à la validation de BBD Officiel.'],['Où mes contacts utilisent-ils mon code ?','Sur la boutique bbd-officiel.fr, au moment de leur commande.'],['Comment utiliser ma cagnotte ?','Elle est déduite directement de vos devis sur ce site professionnel. Dans votre demande de devis, cochez « Utiliser ma cagnotte de parrainage » : le montant déduit figure sur votre devis et dans votre espace pro.'],['Combien me rapporte chaque achat ?','Les conditions du programme, dont le montant crédité sur votre cagnotte et ses modalités d’utilisation, vous sont précisées lors de la validation de votre code.'],['Puis-je choisir mon code ?','Oui, proposez-le dans le formulaire. Il est créé sous réserve de disponibilité ; à défaut, BBD Officiel vous en propose un proche.'],['Faut-il un espace pro ?','C’est là que s’affichent votre code et votre cagnotte. L’espace pro est réservé aux professionnels validés : demandez votre accès à la première connexion, avec la même adresse e-mail que pour votre demande de code.']],'Le parrainage, <em>en clair.</em>')}`,{noCta:true,nav:'/espace-pro/'});

// ---------------------------------------------------------------------------
// Espace pro : suivi des demandes (assets/espace.js, supabase/schema.sql, docs/ESPACE_PRO.md)
// ---------------------------------------------------------------------------
// Sans configuration Supabase, l'état « bientôt » est le seul affiché ; sinon « chargement », puis espace.js prend le relais.
const espaceStates=(admin)=>{
 const st=(name,html)=>`<div class="espace-panel" data-state="${name}"${(supabase?name==='loading':name==='off')?'':' hidden'}>${html}</div>`;
 const steps=[['doc','Demande reçue'],['mail','Devis envoyé'],['check','Commande validée'],['box','En préparation'],['truck','Expédiée'],['paw','Livrée']];
 return `<p class="espace-flash" role="alert" hidden></p>
${st('off',`<div class="espace-box">${icon('lock','ico ico-badge')}<h2>L’espace pro ouvre <em>très bientôt.</em></h2><p>Vous pourrez y suivre chacune de vos demandes, du devis à la livraison. En attendant, envoyez votre demande : nous vous répondons directement.</p><div class="actions">${button('Demander un devis',q('','','','espace-pro'),'big')}</div></div>`)}
${st('loading',`<div class="espace-box espace-box--quiet"><p class="espace-spinner" role="status">Chargement de votre espace…</p><noscript><p class="notice">L’espace pro nécessite JavaScript.</p></noscript></div>`)}
${st('login',`<div class="espace-login-grid"><form class="espace-login espace-box" novalidate><h2>${admin?'Connexion <em>administration.</em>':'Connexion <em>sans mot de passe.</em>'}</h2><p>Indiquez votre adresse e-mail : vous recevez un lien de connexion à usage unique. ${admin?'Seules les adresses autorisées accèdent à la gestion des demandes.':'À la première connexion, vous demandez l’accès : il est ouvert après validation par BBD Officiel.'}</p><div class="field"><label for="espace-email">Votre e-mail *</label><input id="espace-email" name="email" type="email" required autocomplete="email" maxlength="200" placeholder="vous@exemple.fr"></div><button type="submit" class="btn big">Recevoir mon lien de connexion${arrow}</button><p class="espace-small">${icon('lock')}Utilisez la même adresse que pour vos demandes de devis.</p></form>${admin?'':`<aside class="espace-why"><h2>Ce que vous y trouvez</h2><ul>${[['doc','Toutes vos demandes de devis, avec leur référence'],['sliders','L’avancement de chaque commande, étape par étape'],['euro','Le montant de vos devis et les messages de BBD'],['truck','Le numéro de suivi de vos colis expédiés']].map(([i,t])=>`<li>${icon(i)}${t}</li>`).join('')}</ul></aside>`}</div>`)}
${st('sent',`<div class="espace-box">${icon('mail','ico ico-badge')}<h2>Vérifiez <em>votre boîte mail.</em></h2><p>Un lien de connexion vient d’être envoyé à <strong class="espace-sent-email"></strong>. Ouvrez-le sur cet appareil pour accéder à votre espace. Pensez à regarder dans les courriers indésirables.</p><button type="button" class="btn outline" data-espace-retry>Utiliser une autre adresse</button></div>`)}
${admin?'':st('access',`<form class="espace-access espace-box" name="acces-espace-pro" method="POST" action="/espace-pro/" ${(!preview||staging)?'data-netlify="true" netlify-honeypot="bot-field"':''}><input type="hidden" name="form-name" value="acces-espace-pro"><input type="hidden" name="email" value=""><p class="hp"><label>Ne pas remplir <input name="bot-field" tabindex="-1" autocomplete="off"></label></p>${icon('shield','ico ico-badge')}<h2>Demandez l’accès <em>à votre espace pro.</em></h2><p>L’espace pro est réservé aux professionnels du monde canin validés par BBD Officiel. Présentez-vous en quelques mots : votre accès est ouvert après vérification.</p><p class="espace-small">${icon('user')}<span>Connecté : <strong class="espace-user"></strong></span></p><div class="form-grid">${input('acces-nom','Votre nom','text',true,'autocomplete="name"')}${input('acces-structure','Élevage, club ou structure','text',true,'autocomplete="organization"')}${select('acces-profil','Vous êtes',[['eleveur','Éleveur'],['club','Club de race / de discipline'],['organisateur','Organisateur d’événements'],['partenaire','Partenaire du monde canin'],['autre','Autre structure']],true)}${input('acces-telephone','Téléphone','tel',false,'autocomplete="tel"')}${input('acces-site','Site, réseau social ou n° d’affixe / SIRET','text',false,'placeholder="Facultatif, facilite la vérification"')}</div><label class="check"><input type="checkbox" name="acces-confidentialite" value="lu" required><span>J’ai pris connaissance de la <a href="/confidentialite/" target="_blank" rel="noopener">politique de confidentialité (nouvel onglet)</a>. *</span></label><button type="submit" class="btn big">Envoyer ma demande d’accès${arrow}</button><p class="espace-small">${icon('lock')}Aucun paiement, aucun engagement : l’accès sert à suivre vos devis et votre parrainage.</p></form>`)}
${admin?'':st('pending',`<div class="espace-box">${icon('doc','ico ico-badge')}<h2>Votre demande est <em>en cours de validation.</em></h2><p>Merci ! BBD Officiel vérifie la demande d’accès de <strong class="espace-user"></strong>. Dès qu’elle est validée, vous retrouvez ici vos devis, leur avancement et votre parrainage. En attendant, vous pouvez déjà nous envoyer une demande de devis.</p><div class="actions">${button('Demander un devis',q('','','','espace-attente'))}<button type="button" class="btn outline" data-espace-logout>Me déconnecter</button></div></div>`)}
${admin?'':st('refused',`<div class="espace-box">${icon('lock','ico ico-badge')}<h2>Accès <em>non validé.</em></h2><p>La demande d’accès de <strong class="espace-user"></strong> n’a pas été retenue.</p><p class="espace-refused-note" hidden></p><p>Vous pouvez toujours nous écrire au moyen d’une demande de devis.</p><div class="actions">${button('Demander un devis',q('','','','espace-refus'))}<button type="button" class="btn outline" data-espace-logout>Me déconnecter</button></div></div>`)}
${st('denied',`<div class="espace-box">${icon('lock','ico ico-badge')}<h2>Accès <em>réservé.</em></h2><p>L’adresse <strong class="espace-user"></strong> n’est pas autorisée à gérer les demandes.</p><div class="actions">${button('Aller à mon espace client','/espace-pro/')}<button type="button" class="btn outline" data-espace-logout>Me déconnecter</button></div></div>`)}
${st('dashboard',`<div class="espace-bar"><p>${icon('user')}<span>Connecté : <strong class="espace-user"></strong></span></p><p class="espace-count"></p>${admin?`<label class="espace-filter-label">Afficher <select class="espace-filter"><option value="">Toutes les demandes</option>${[['recue','Demande reçue'],['devis_envoye','Devis envoyé'],['validee','Commande validée'],['preparation','En préparation'],['expediee','Expédiée'],['livree','Livrée'],['annulee','Annulée']].map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label>`:button('Nouvelle demande',q('','','','espace-pro'),'')}<button type="button" class="btn outline" data-espace-logout>Me déconnecter</button></div>${admin?'':`<div class="espace-parrain" hidden></div><div class="espace-empty espace-box" hidden>${icon('doc','ico ico-badge')}<h2>Aucune demande <em>pour le moment.</em></h2><p>Les demandes de devis envoyées lorsque vous êtes connecté apparaissent ici automatiquement, avec leur avancement.</p><div class="actions">${button('Demander un devis',q('','','','espace-pro'),'big')}${button('Voir les catalogues','/solutions/','outline big')}</div></div>`}${admin?'<section class="espace-admin-parrain espace-admin-membres" aria-labelledby="admin-membres-title"><h2 id="admin-membres-title">Accès <em>à l’espace pro.</em></h2><p class="espace-admin-help">Chaque professionnel qui se connecte pour la première fois demande l’accès. Validez-le pour qu’il suive ses devis et son parrainage ; refusez-le si besoin, avec un message.</p><div class="espace-membres-admin"></div></section>':''}${admin?'<section class="espace-admin-parrain" aria-labelledby="admin-parrain-title"><h2 id="admin-parrain-title">Codes de <em>parrainage.</em></h2><p class="espace-admin-help">Après validation d’une demande reçue par e-mail, créez le code ici avec l’adresse e-mail du professionnel : il le verra dans son espace avec sa cagnotte. Créditez la cagnotte au fil des achats réalisés avec son code sur bbd-officiel.fr, et déduisez-la lorsqu’elle est utilisée sur un devis.</p><div class="espace-parrain-admin"></div></section><h2 class="espace-admin-title">Demandes <em>de devis.</em></h2>':''}<div class="espace-list"></div>`)}
${admin?'':parrainPromo()}${admin?'':`<section class="espace-how"><h2>Le parcours <em>de votre commande.</em></h2><ol class="espace-how-steps">${steps.map(([i,t],n)=>`<li>${icon(i)}<span><small>Étape ${n+1}</small>${t}</span></li>`).join('')}</ol><p>Chaque étape est mise à jour par BBD Officiel au fil de votre commande. Le paiement ne se fait jamais sur le site.</p></section>`}`;
};
page('/espace-pro/','Espace pro — Suivre mes demandes','Connectez-vous à votre espace pro BBD Officiel pour suivre vos demandes de devis et vos commandes, du devis à la livraison.',`${crumbs('Espace pro')}<section class="wrap espace" data-espace="client"><div class="espace-hero"><p class="kicker">${icon('user')}Espace pro</p><h1>Vos demandes,<br><em>suivies de près.</em></h1><p class="lead">Retrouvez vos demandes de devis et suivez chaque commande, de la proposition à la livraison. Un espace réservé aux professionnels validés par BBD Officiel, sans mot de passe : un lien de connexion par e-mail suffit.</p></div>${espaceStates(false)}</section>`,{noCta:true,espace:true});
page('/espace-pro/admin/','Espace pro — Administration','Gestion des demandes de l’espace pro BBD Officiel.',`<section class="wrap espace" data-espace="admin"><div class="espace-hero"><p class="kicker">${icon('lock')}Administration</p><h1>Les demandes<br><em>de vos clients.</em></h1><p class="lead">Mettez à jour le statut, le montant du devis, le suivi du colis et votre message : le client le voit aussitôt dans son espace.</p></div>${espaceStates(true)}</section>`,{noCta:true,espace:true,nav:''});
page('/mentions-legales/','Mentions légales','Informations sur l’éditeur et l’hébergeur du site BBD Officiel.',`${crumbs('Mentions légales')}<section class="wrap section prose"><h1>Mentions légales</h1>${preview?'<div class="notice warning">Document de travail. Informations à compléter et à valider avant publication.</div>':''}<h2>Éditeur du site</h2><p>${esc(config.company||'Raison sociale à renseigner')}<br>${esc(config.legalStatus||'Forme juridique et capital, si applicable, à renseigner')}<br>${esc(config.address||'Adresse professionnelle à renseigner')}<br>${esc(config.registration||'Immatriculation à renseigner')}<br>${esc(config.vat||'TVA : régime à préciser si applicable')}</p><h2>Directeur de la publication</h2><p>${esc(config.director||'Identité à renseigner')}</p><h2>Contact</h2><p>${esc(config.email||'Adresse e-mail professionnelle à renseigner')}${config.phone?'<br>'+esc(config.phone):''}</p><h2>Hébergement prévu</h2><p>${esc(config.hostLegal||"Netlify. Coordonnées légales de l’hébergeur à vérifier et à compléter avant publication.")}</p><h2>Contenus et droits</h2><p>Les illustrations de cette maquette ont été dessinées pour le site. Les logos, photographies et réalisations fournis ultérieurement devront disposer des autorisations nécessaires à leur utilisation. Les exemples de formules de l’aperçu ne constituent pas des offres commerciales confirmées.</p></section>`,{noCta:true});
page('/confidentialite/','Politique de confidentialité','Utilisation des informations transmises dans une demande de devis auprès de BBD Officiel.',`${crumbs('Confidentialité')}<section class="wrap section prose"><h1>Vos informations,<br><em>en toute clarté.</em></h1>${preview?'<div class="notice warning">Document de travail : aucun envoi dans l’aperçu local. Les informations ci-dessous devront être complétées et validées avant l’ouverture du formulaire public.</div>':''}<h2>Qui est responsable ?</h2><p>${esc(config.company||'Responsable du traitement à renseigner')} — ${esc(config.privacyContact||'Contact dédié à vos données à renseigner')}.</p><h2>Pourquoi ces informations ?</h2><p>Le formulaire recueille votre nom, votre e-mail, votre profil, votre besoin et les informations complémentaires que vous choisissez de fournir. Ces éléments servent à traiter la demande et à préparer les échanges commerciaux associés. Aucun abonnement à des communications promotionnelles n’est ajouté automatiquement.</p><p>Base juridique : ${esc(config.legalBasis||'à déterminer et valider par le responsable de l’activité')}.</p><h2>Provenance de la demande</h2><p>Le contexte choisi (univers, formule ou produit) est joint à la demande. Lorsqu’un lien de salon contient un identifiant de campagne, cet identifiant est transmis avec le formulaire pour retrouver le contexte de l’échange. Aucun cookie publicitaire ni outil d’analyse tiers n’est intégré au site.</p><h2>Espace pro</h2><p>Si vous créez un espace pro, nous enregistrons votre adresse e-mail, les informations de votre demande d’accès (nom, structure, profil, téléphone, site) et la décision de validation, la date de vos connexions et les demandes envoyées lorsque vous êtes connecté, ainsi que leur suivi (statut, montant du devis, numéro de suivi, messages de BBD Officiel). La connexion se fait par un lien envoyé par e-mail, sans mot de passe. Un jeton de session est conservé dans votre navigateur jusqu’à la déconnexion. Ces données sont hébergées par le prestataire Supabase ; la région d’hébergement et la durée de conservation seront précisées dans la version validée.</p><h2>Programme de parrainage</h2><p>La demande de code de parrainage recueille votre profil, le nom de votre structure, vos coordonnées, le code souhaité et vos idées de diffusion, afin d’étudier votre demande. Si elle est validée, votre adresse e-mail, votre code et le montant de votre cagnotte sont conservés pour l’afficher dans votre espace pro et la déduire de vos devis.</p><h2>Destinataires et hébergement</h2><p>${esc(config.recipients||'Destinataires et prestataires à confirmer, notamment les personnes habilitées chez BBD Officiel et Netlify pour la réception des formulaires.')}</p><p>${esc(config.internationalTransfers||'Les modalités d’hébergement et les éventuels transferts internationaux doivent être vérifiés et documentés avant publication.')}</p><h2>Durée de conservation</h2><p>${esc(config.retention||'À définir par BBD Officiel à partir de ses pratiques réelles. Aucune durée n’a été supposée pour cette maquette.')}</p><h2>Vos droits et votre contact</h2><p>${esc(config.rightsText||'Les modalités d’exercice de vos droits, les droits applicables à la base juridique retenue et le recours auprès de la CNIL seront précisés dans la version validée.')}</p><p>${esc(config.privacyContact||'Adresse de contact à compléter')}.</p></section>`,{noCta:true});
page('/apercu/','À compléter ensemble','Les éléments attendus pour transformer la structure BBD Officiel en site public.',`${crumbs('Aperçu de travail')}${intro('Une base qui évolue avec vous','Le cadre est posé.<br><em>À vous de lui donner vie.</em>','Cette version permet de tester le design, les parcours et les exemples de formules. Les informations réelles seront ajoutées au fil de vos envois.')}<section class="wrap section"><div class="use-grid">${[['Votre identité','Logo, coordonnées publiques, histoire et informations légales.'],['Vos offres','Formules, références, variantes, techniques de personnalisation et conditions confirmées.'],['Vos images','Photographies de produits, moments de terrain et réalisations dont la publication est autorisée.'],['La mise en ligne','Compte Netlify gratuit, adresse de réception, validation des contenus, taux de TVA et test réel du formulaire.']].map(([t,d])=>`<article class="use-card"><h2>${t}</h2><p>${d}</p></article>`).join('')}</div></section>`,{noCta:true});
page('/404.html','Page introuvable','Retrouvez les catalogues et univers BBD Officiel.',`<section class="wrap success">${eyebrow('Erreur 404')}<h1>Ce chemin<br><em>ne mène plus ici.</em></h1><p>Retrouvez les catalogues ou revenez à l’accueil pour poursuivre votre projet.</p><div class="actions">${button('Voir les catalogues','/solutions/')}${button('Revenir à l’accueil','/','outline')}</div></section>`,{noCta:true});
fs.writeFileSync(path.join(dist,'robots.txt'),preview?'User-agent: *\nDisallow: /\n':`User-agent: *\nAllow: /\nSitemap: ${config.url.replace(/\/$/,'')}/sitemap.xml\n`);
const indexable=pages.filter(p=>!['/404.html','/merci/','/apercu/','/espace-pro/','/espace-pro/admin/'].includes(p));
fs.writeFileSync(path.join(dist,'sitemap.xml'),`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${config.url?indexable.map(p=>`<url><loc>${esc(config.url.replace(/\/$/,'')+p)}</loc></url>`).join(''):''}</urlset>`);
fs.writeFileSync(path.join(dist,'_redirects'),'/a-propos/ /qui-sommes-nous/ 301\n/produits/bb-bed-100x150/ /solutions/accessoires/ 301\n/catalogue/ /solutions/ 301\n/demander-un-devis/ /devis/ 301\n/* /404.html 404\n');
console.log(`${pages.length} pages générées (${production?'production':staging?'test de réception':'aperçu sans envoi'}).`);
